 bodies['about']=section('01',t('From business potential<br>to enterprise performance.','من إمكانات الأعمال<br>إلى أداء مؤسسي قابل للنمو.'),f'<p class="lead">{about}</p>')+section('02',t('Our core.','مرتكزاتنا.'),blocks(t(['Purpose','Vision','Mission'],['الغرض','الرؤية','الرسالة']),t(['Begin with the business objective, then align the structure, capability and execution required to move it forward.','To become a recognised platform for building, developing and scaling high-potential businesses.','To turn business opportunities and existing enterprises into structured and scalable organisations by integrating strategy, specialist capability, operational development and disciplined execution.'],['نبدأ من هدف الأعمال، ثم نوائم الهيكل والقدرات والتنفيذ اللازم لدفعه إلى الأمام.','أن تصبح بزنس أوربت منصة معترفاً بها لبناء وتطوير وتوسيع الأعمال عالية الإمكانات.','تحويل فرص الأعمال والمنشآت القائمة إلى كيانات مهيكلة وقابلة للتوسع من خلال تكامل الاستراتيجية والقدرات التخصصية والتطوير التشغيلي والتنفيذ المنضبط.'])))
 fields=[('name',t('Full name','الاسم الكامل'),'text'),('email',t('Work email','البريد الإلكتروني للعمل'),'email'),('company',t('Organisation','المنشأة'),'text')]
 form=''.join(f'<label>{label}<input name="{name}" type="{typ}" autocomplete="'+{'name':'name','email':'email','company':'organization'}[name]+'" required maxlength="180"></label>' for name,label,typ in fields)
