  header='<a class="skip" href="#main">'+t('Skip to content','انتقل إلى المحتوى')+'</a><header><a class="brand" href="/'+lang+'/"><img src="/assets/logo.png" alt="Business Orbit" width="88" height="97"><span>'+t('BUSINESS<br>ORBIT','بزنس<br>أوربت')+'</span></a><button id="menu" aria-expanded="false" aria-controls="navigation">'+t('Menu','القائمة')+'</button><nav id="navigation" aria-label="'+t('Main navigation','التنقل الرئيسي')+'">'+''.join(f'<a '+('aria-current="page"' if slug==s else '')+f' href="/{lang}/{s}/">{n}</a>' for s,n in zip(slugs,nav[lang]))+'</nav><a class="lang" href="/'+alt+'/'+(slug+'/' if slug else '')+'" lang="'+alt+'">'+t('العربية','EN')+'</a></header>'
  hero=f'<section class="hero {"home" if not slug else "inner"}"><div><div class="eyebrow">'+t('RIYADH / INTEGRATED BUSINESS DEVELOPMENT & EXECUTION','الرياض / منصة متكاملة لتطوير الأعمال والتنفيذ')+f'</div><h1>{title}</h1><p class="lead">{intro}</p>'+link('contact',t('Start a conversation','ابدأ الحوار'),'button')+(link('business-model',t('Explore the model','استكشف النموذج')) if not slug else '')+'</div>'+ (orbit() if not slug else '<div class="hero-index" aria-hidden="true">'+('OS' if slug=='intelligence-os' else 'BO')+'</div>')+'</section>'
