  path=f'/{lang}/'+(slug+'/' if slug else '')
  doc=f'<!doctype html><html lang="{lang}" dir="'+('rtl' if lang=='ar' else 'ltr')+'"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>'+esc(title)+' | Business Orbit</title><meta name="description" content="'+esc(intro)+'"><meta property="og:title" content="'+esc(title)+' | Business Orbit"><meta property="og:description" content="'+esc(intro)+'"><meta property="og:type" content="website"><link rel="alternate" hreflang="en" href="/en/'+(slug+'/' if slug else '')+'"><link rel="alternate" hreflang="ar" href="/ar/'+(slug+'/' if slug else '')+'"><link rel="stylesheet" href="/assets/style.css"><script defer src="/assets/app.js"></script></head><body>'+header+'<main id="main">'+hero+bodies[slug]+'</main>'+footer+'</body></html>'
  out=D/lang/slug;out.mkdir(parents=True,exist_ok=True);(out/'index.html').write_text(doc);P[path]=title
